examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    messages.forEachIndexed { index, it ->
        val who = (if (it.role == MonarchAiRole.User) "You" else (it.agent?.name ?: "Assistant")) + ":"
        Text(
            text = buildAnnotatedString {
                append("${index + 1}. ")
                withStyle(SpanStyle(fontWeight = FontWeight.SemiBold)) { append(who) }
                append(" " + it.text)
            },
            style = MonarchTheme.typography.body,
            color = MonarchTheme.colors.textDefault,
        )
    }
    MonarchText(text = "Status: " + status.name.lowercase())
    Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
        MonarchTextField(
            value = draft,
            onValueChange = { draft = it },
            modifier = Modifier.weight(1f),
            label = "Message",
            labelVisibility = MonarchTextFieldLabelVisibility.Hidden,
            placeholder = {{placeholder}},
        )
        MonarchButton(
            text = "Send",
            onClick = {
                conversation.send(draft)
                draft = ""
            },
            variant = MonarchButtonVariant.Primary,
        )
        MonarchButton(
            text = "Regenerate",
            onClick = { conversation.regenerate() },
            variant = MonarchButtonVariant.Ghost,
            enabled = !conversation.busy && messages.isNotEmpty(),
        )
    }
}

examples.setupTemplate:
val transport = remember {
    object : MonarchAiTransport {
        override fun stream(request: MonarchAiTransportRequest): Flow<MonarchAiStreamEvent> = flowOf(
            MonarchAiStreamEvent.TextDelta("You asked: “" + request.messages.lastOrNull()?.text.orEmpty() + "”. This reply is streamed word by word from a mock transport."),
            MonarchAiStreamEvent.Done(),
        )
    }
}
val conversation = rememberMonarchAiConversation(
    transport,
    initialMessages = listOf(
        MonarchAiConversationMessage(id = {{messages.0.id}}, role = MonarchAiRole.{{messages.0.role|pascal}}, parts = listOf(MonarchAiTextPart({{messages.0.text}})), createdAt = {{messages.0.createdAt}}),
        MonarchAiConversationMessage(id = {{messages.1.id}}, role = MonarchAiRole.{{messages.1.role|pascal}}, parts = listOf(MonarchAiTextPart({{messages.1.text}})), createdAt = {{messages.1.createdAt}}, agent = MonarchAiAgentRef(name = {{messages.1.agent}})),
    ),
)
val messages by conversation.messages.collectAsState()
val status by conversation.status.collectAsState()
var draft by remember { mutableStateOf("") }

