examples.setup:
val transport = remember {
    object : MonarchAiTransport {
        override fun stream(request: MonarchAiTransportRequest): Flow<MonarchAiStreamEvent> = flowOf(
            MonarchAiStreamEvent.TextDelta("You asked: "),
            MonarchAiStreamEvent.TextDelta(request.messages.lastOrNull()?.text.orEmpty()),
            MonarchAiStreamEvent.Done(),
        )
    }
}
val conversation = rememberMonarchAiConversation(transport)
val messages by conversation.messages.collectAsState()
val status by conversation.status.collectAsState()

examples.code:
Column {
    messages.lastOrNull()?.let { reply ->
        MonarchText(text = reply.text)
        reply.branch?.let { branch ->
            MonarchButton(
                text = "Previous version",
                onClick = { conversation.branchTo(reply.id, branch.index - 1) },
                enabled = branch.index > 0,
            )
        }
    }
    MonarchButton(text = "Stop", onClick = { conversation.stop() }, enabled = conversation.busy)
    MonarchButton(text = "Regenerate", onClick = { conversation.regenerate() })
}
